  "headline": "FDA's records trace our supply to a plant classified OAI 217 days before the posting",
  "headline_cites": ["D12"],
  "sentences": [
    {
      "text": "Propofol is on FDA's shortage list, first posted 2020-04-10, and has been listed for 78 months as of 2026-10-21.",
      "cites": ["D17"]
    },
    {
      "text": "FDA inspection 1106244 at Pfizer Healthcare India Private Limited ended 2019-09-06 and was classified OAI, with the classification letter dated 2020-05-25, 217 days before the shortage posting.",
      "cites": ["D12", "E15"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2020-03-25, 16 days before the posting.",
      "cites": ["D14", "E17"]
    },
    {
      "text": "Corvale General holds 343 vials of the 20 mL presentation at 15.8 vials per day, providing 21.7 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale Lakeside holds 10 vials of the 20 mL presentation at 2 vials per day, providing 5 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "The top-ranked option is to transfer 18 vials of 10 mg/mL, 20 mL from Corvale General to Corvale Lakeside, which would give Corvale General two weeks of supply and bring Corvale Lakeside to 14 days.",
      "cites": ["D18"]
    }
  ]
}
